def transform(grid):
    R, C = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    others = [c for c in cnt if c != bg]
    out = [row[:] for row in grid]
    if not others:
        return out
    line = others[0]

    def is_gap(y, x):
        if grid[y][x] != bg:
            return False
        if y > 0 and y < R - 1 and grid[y-1][x] == line and grid[y+1][x] == line:
            return True
        if x > 0 and x < C - 1 and grid[y][x-1] == line and grid[y][x+1] == line:
            return True
        return False

    # prefix sums of bg cells for fast all-bg rectangle checks
    ps = [[0] * (C + 1) for _ in range(R + 1)]
    for i in range(R):
        for j in range(C):
            ps[i+1][j+1] = ps[i][j+1] + ps[i+1][j] + (1 if grid[i][j] == bg else 0) - ps[i][j]

    def all_bg(r1, r2, c1, c2):
        return ps[r2+1][c2+1] - ps[r1][c2+1] - ps[r2+1][c1] + ps[r1][c1] == (r2-r1+1)*(c2-c1+1)

    def side_wall(cells):
        return all(grid[y][x] == line or is_gap(y, x) for y, x in cells)

    fill = set()
    for r1 in range(R):
        for r2 in range(r1, R):
            for c1 in range(C):
                for c2 in range(c1, C):
                    area = (r2 - r1 + 1) * (c2 - c1 + 1)
                    if area < 2:
                        continue
                    if not all_bg(r1, r2, c1, c2):
                        continue
                    borders = 0
                    ok = True
                    # top
                    if r1 == 0:
                        borders += 1
                    elif not side_wall([(r1 - 1, x) for x in range(c1, c2 + 1)]):
                        ok = False
                    # bottom
                    if ok:
                        if r2 == R - 1:
                            borders += 1
                        elif not side_wall([(r2 + 1, x) for x in range(c1, c2 + 1)]):
                            ok = False
                    # left
                    if ok:
                        if c1 == 0:
                            borders += 1
                        elif not side_wall([(y, c1 - 1) for y in range(r1, r2 + 1)]):
                            ok = False
                    # right
                    if ok:
                        if c2 == C - 1:
                            borders += 1
                        elif not side_wall([(y, c2 + 1) for y in range(r1, r2 + 1)]):
                            ok = False
                    if ok and borders <= 1:
                        for y in range(r1, r2 + 1):
                            for x in range(c1, c2 + 1):
                                fill.add((y, x))
    for y, x in fill:
        out[y][x] = 4
    return out
